function tarifa(peso, destino, esSocio) {
  if (peso > 30) return null;
  let p;
  if (peso <= 2) p = 3.95;
  else if (peso <= 10) p = 5.90;
  else p = 5.90 + 0.45 * (peso - 10);
  let t;
  switch (destino) {
    case 'peninsula': t = p; break;
    case 'baleares':
    case 'canarias': t = p * 1.8; break;
    default: return null;
  }
  if (esSocio) { t = peso < 1 ? 0 : t * 0.85; }
  return t;
}
